//! 🧪️ Actual original source pointers survive bounded preparation, denial, guest acknowledgement and whole-source closure.
use super::*;
use semio_framework_job::{OperationId, Generation, StepBudget, OriginalCallerSourceParent};
use semio_framework_job_payload::{JobPayloadAuthority};
use semio_framework_async::CancelToken;
fn heap<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,system)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(system.requested_bytes,system.released_bytes))}
fn minimum(left:RetainedCloneGrant,right:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:left.maximum_items.min(right.maximum_items),maximum_copy_bytes:left.maximum_copy_bytes.min(right.maximum_copy_bytes),maximum_capacity_bytes:left.maximum_capacity_bytes.min(right.maximum_capacity_bytes),maximum_release_bytes:left.maximum_release_bytes.min(right.maximum_release_bytes),maximum_depth:left.maximum_depth.min(right.maximum_depth)}}
#[test]
fn original_job_source_keeps_actual_source_and_absolute_deadline_without_refill(){
 for copy in [1,3,64]{for stop in [None,Some(0),Some(5)]{
  let mut input=RetainedTurnInput{operation:71,generation:3,epoch:19,work:crate::OriginalActorTurnWork{clock_binding:1,absolute_deadline_us:12345,fuel:1000000},grant:RetainedCloneGrant{maximum_items:100000,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:128}};
  let policy=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:128};
  let((cancel,birth),system)=heap(||CancelToken::admit_root(input.grant).unwrap().unwrap());assert_eq!(system,(birth.retained_capacity_bytes,birth.released_bytes));let mut allocated=system.0;let mut released=system.1;input=returned(input,birth,birth.copied_items as u64);
  let((mut payload,birth),system)=heap(||JobPayloadAuthority::admit(OperationId(input.operation),Generation(input.generation),input.grant).unwrap().unwrap());assert_eq!(system,(birth.retained_capacity_bytes,birth.released_bytes));allocated+=system.0;released+=system.1;input=returned(input,birth,birth.copied_items as u64);
  let((mut parent,birth),system)=heap(||OriginalCallerSourceParent::admit(payload,cancel,input.grant).ok().unwrap());assert_eq!(system,(birth.retained_capacity_bytes,birth.released_bytes));allocated+=system.0;released+=system.1;input=returned(input,birth,birth.copied_items as u64);
  let(source,system)=heap(||{let mut kind=String::with_capacity(63);kind.push_str("actual.source.源");let mut bytes=Vec::with_capacity(101);bytes.extend(0u8..97);let mut checkpoint=Vec::with_capacity(33);checkpoint.extend_from_slice(&[8,7,6,5,4]);OriginalJobSource{job:11,kind,input:Some(bytes),checkpoint:Some(checkpoint)}});allocated+=system.0;released+=system.1;let pointers=(source.kind.as_ptr(),source.input.as_ref().unwrap().as_ptr(),source.checkpoint.as_ref().unwrap().as_ptr());let oracle=serde_json::to_value(&source).unwrap();let(mut owner,system)=heap(||OriginalJobSourceCursor::new(source,input).ok().unwrap());assert_eq!(system,(0,0));let mut sequence=0;let mut prepared=None;let mut complete=false;
  for turn in 0..100000{
   let checked=RetainedTurnInput{grant:minimum(input.grant,policy),..input};if turn==0{let zero=RetainedTurnInput{grant:RetainedCloneGrant{maximum_items:0,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:0},..checked};let mut recipient=Default::default();let mut zero_cx=context(&parent,input,zero.grant,&mut sequence,&mut recipient);let(result,system)=heap(||owner.advance(&mut zero_cx));assert!(!result.unwrap());assert_eq!(system,(0,0));assert_eq!(zero_cx.retained_progress(),Default::default());}
   let mut spent=Default::default();let mut cx=context(&parent,input,checked.grant,&mut sequence,&mut spent);let loan=OriginalJobBudget::borrow_original(checked,&cx).unwrap();assert_eq!(loan.deadline_us,12345);assert_eq!(loan.input,checked);let mut crossing=OriginalJobTurnLoan::new();let(issued,system)=heap(||crossing.checkout(checked,&cx).unwrap().unwrap());assert_eq!(system,(0,0));assert_eq!(issued.fuel,7);assert_eq!(crossing.clock_source().unwrap() as usize,cx.clock_source() as usize);let(debited,system)=heap(||crossing.receive(issued.input,Default::default(),4,&mut cx));debited.unwrap();assert_eq!(system,(0,0));assert_eq!(cx.fuel_remaining(),3);assert!(crossing.receive(issued.input,Default::default(),4,&mut cx).is_err());assert_eq!(cx.fuel_remaining(),3);let remaining=RetainedTurnInput::borrow_original(&cx).unwrap();let next=crossing.checkout(remaining,&cx).unwrap().unwrap();assert_eq!(next.fuel,3);assert_eq!(next.deadline_us,12345);crossing.receive(next.input,Default::default(),0,&mut cx).unwrap();assert!(crossing.terminal_is_empty());assert_eq!(heap(||drop(crossing)).1,(0,0));

   let(result,system)=heap(||if stop==Some(turn){owner.begin_close();Ok(false)}else{owner.advance(&mut cx)});complete=result.unwrap();assert_eq!(system,(cx.retained_progress().retained_capacity_bytes,cx.retained_progress().released_bytes));allocated+=system.0;released+=system.1;let work=u64::try_from(cx.original_work_units_spent()).unwrap();drop(cx);let receipt=checked.return_original(spent,work).unwrap();input=returned(input,receipt.spent,receipt.work_units_spent);let original=owner.original().unwrap();assert_eq!((original.kind.as_ptr(),original.input.as_ref().unwrap().as_ptr(),original.checkpoint.as_ref().unwrap().as_ptr()),pointers);assert_eq!(serde_json::to_value(original).unwrap(),oracle);if complete||stop==Some(turn){break}assert!(turn<99999,"actual original source preparation stalled")
  }
  if complete{let checked=RetainedTurnInput{grant:minimum(input.grant,policy),..input};let mut spent=Default::default();let mut cx=context(&parent,input,checked.grant,&mut sequence,&mut spent);let(result,system)=heap(||owner.take_prepared(&mut cx));prepared=result.unwrap();assert_eq!(system,(0,0));assert_eq!(cx.retained_progress().copied_bytes,0);assert_eq!(cx.retained_progress().copied_items,1);let work=u64::try_from(cx.original_work_units_spent()).unwrap();drop(cx);input=returned(input,spent,work);assert_eq!(serde_json::to_value(prepared.as_ref().unwrap()).unwrap(),oracle);assert!(owner.source_outstanding());let(result,system)=heap(||owner.retirement_demands(copy));assert!(result.is_err());assert_eq!(system,(0,0));let mut returned_source=prepared.take();let mut spent=Default::default();let checked=RetainedTurnInput{grant:minimum(input.grant,policy),..input};let mut cx=context(&parent,input,checked.grant,&mut sequence,&mut spent);let(result,system)=heap(||owner.receive_returned(&mut returned_source,&mut cx));assert!(result.unwrap());assert_eq!(system,(0,0));assert!(returned_source.is_none());let work=u64::try_from(cx.original_work_units_spent()).unwrap();drop(cx);input=returned(input,spent,work);}
  assert!(prepared.is_none());owner.begin_close();for turn in 0..100000{if owner.terminal_is_empty(){break}let checked=RetainedTurnInput{grant:minimum(input.grant,policy),..input};let mut spent=Default::default();let mut cx=context(&parent,input,checked.grant,&mut sequence,&mut spent);let(result,system)=heap(||owner.close_step(&mut cx));result.unwrap();assert_eq!(system,(cx.retained_progress().retained_capacity_bytes,cx.retained_progress().released_bytes));allocated+=system.0;released+=system.1;let work=u64::try_from(cx.original_work_units_spent()).unwrap();drop(cx);input=returned(input,spent,work);assert!(turn<99999,"actual original source closure stalled")}
  assert_eq!(heap(||drop(owner)).1,(0,0));while !parent.terminal_is_empty(){let(step,system)=heap(||parent.close_step(input.grant).unwrap());assert_eq!(system,(step.progress().retained_capacity_bytes,step.progress().released_bytes));allocated+=system.0;released+=system.1;input=returned(input,step.progress(),step.progress().copied_items as u64);}assert_eq!(heap(||drop(parent)).1,(0,0));assert_eq!(allocated,released);
 }}
}

fn returned(input:RetainedTurnInput,spent:RetainedCloneProgress,work:u64)->RetainedTurnInput{let receipt=input.return_original(spent,work).unwrap();RetainedTurnInput{epoch:input.epoch+1,grant:receipt.remaining,work:crate::OriginalActorTurnWork{fuel:receipt.remaining_fuel,..input.work},..input}}
fn context<'a>(parent:&'a OriginalCallerSourceParent,input:RetainedTurnInput,policy:RetainedCloneGrant,sequence:&'a mut u64,spent:&'a mut RetainedCloneProgress)->StepContext<'a>{let mut cx=parent.borrow_context(StepBudget::new(input.work.fuel,input.work.absolute_deadline_us,input.grant),semio_framework_job::logical_now_us,sequence,spent).unwrap();cx.bind_original_clock_binding(input.work.clock_binding).unwrap();cx.bind_original_source_epoch(input.epoch).unwrap();cx.narrow_original_work_budget(StepBudget::new(input.work.fuel.min(7),input.work.absolute_deadline_us,policy)).unwrap();cx}
